-- Run after setup.sql in the Supabase SQL Editor. Safe to run again.
-- Shared reports contain only anonymous aggregates of matching built-in cards.
create table if not exists public.study_statistics_catalog (
 lecture_id text not null,card_id text not null,content_key text not null,
 module_id text not null,lecture_title text not null,topic text not null,slide integer not null,prompt text not null,
 primary key(lecture_id,card_id)
);
alter table public.study_statistics_catalog enable row level security;
revoke all on public.study_statistics_catalog from public,anon,authenticated;

create or replace function public.study_statistics_dashboard()
returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare result jsonb;
begin
 if auth.uid() is null then raise exception 'Sign in to view shared statistics'; end if;
 with events as (
  select distinct on(d.user_id,e.key) d.user_id,d.lecture_id,e.key,e.value
  from public.study_decks d
  cross join lateral jsonb_each(case when jsonb_typeof(d.payload->'_reviewEvents')='object' then d.payload->'_reviewEvents' else '{}'::jsonb end) e
  where e.value->>'rating' in ('again','hard','good','easy') and e.value->>'id'=e.key
  order by d.user_id,e.key,d.lecture_id
 ), totals as (
  select r.lecture_id,r.card_id,r.module_id,r.lecture_title,r.topic,r.slide,r.prompt,
   count(*) filter(where e.value->>'rating' in ('good','easy')) correct,
   count(*) filter(where e.value->>'rating'='again') incorrect,
   count(*) filter(where e.value->>'rating'='hard') partial
  from events e join public.study_statistics_catalog r on r.lecture_id=e.lecture_id
   and r.card_id=e.value->>'cardId' and r.content_key=e.value->>'contentKey'
  group by r.lecture_id,r.card_id,r.module_id,r.lecture_title,r.topic,r.slide,r.prompt
  having count(distinct e.user_id)>=3 and count(*)>=5
 ) select coalesce(jsonb_agg(jsonb_build_object('lectureId',lecture_id,'cardId',card_id,'moduleId',module_id,
  'lectureTitle',lecture_title,'topic',topic,'slide',slide,'prompt',prompt,'correct',correct,'incorrect',incorrect,'partial',partial)
  order by lecture_id,card_id),'[]'::jsonb) into result from totals;
 return jsonb_build_object('cards',result);
end;$$;
revoke all on function public.study_statistics_dashboard() from public,anon;
grant execute on function public.study_statistics_dashboard() to authenticated;

-- Canonical catalog below prevents private uploads/edited wording entering public reports.
on conflict(lecture_id,card_id) do update set content_key=excluded.content_key,module_id=excluded.module_id,lecture_title=excluded.lecture_title,topic=excluded.topic,slide=excluded.slide,prompt=excluded.prompt;
